                paragraphs = listOf(
                    StoryParagraph("In the 1930s, a terrible drought hit the southern plains of the United States.", "در دهه ۱۹۳۰، خشکسالی وحشتناکی دشت‌های جنوبی ایالات متحده را درنوردید."),
                    StoryParagraph("The land that had once been green and fertile turned into a dry, dusty desert.", "زمینی که زمانی سبز و حاصلخیز بود، به بیابانی خشک و غبارآلود تبدیل شد."),
                    StoryParagraph("Farmers watched helplessly as their crops withered and died in the fields.", "کشاورزان درمانده تماشا می‌کردند که محصولاتشان در مزارع پژمرده و می‌میرند."),
                    StoryParagraph("The wind blew constantly, carrying clouds of dust that blocked out the sun.", "باد به طور مداوم می‌وزید و ابرهای غبار را با خود می‌آورد که خورشید را می‌پوشاند."),
                    StoryParagraph("Dust seeped into houses through every crack and covered everything in a thick, gray layer.", "غبار از هر شکافی به خانه‌ها نفوذ می‌کرد و همه چیز را با لایه‌ای ضخیم و خاکستری می‌پوشاند."),
                    StoryParagraph("People tied handkerchiefs over their faces just to breathe, and they wore goggles to protect their eyes.", "مردم برای نفس کشیدن دستمال به صورت می‌بستند و برای محافظت از چشمانشان عینک می‌زدند."),
                    StoryParagraph("Animals died in the fields, and children grew sick from the dust in their lungs.", "حیوانات در مزارع می‌مردند و کودکان از غبار در ریه‌هایشان بیمار می‌شدند."),
                    StoryParagraph("This region became known as the Dust Bowl, and it was one of the worst disasters in American history.", "این منطقه به «کاسه غبار» معروف شد و یکی از بدترین فاجعه‌های تاریخ آمریکا بود."),
                    StoryParagraph("The Joad family lived in this region, on a small farm in Oklahoma.", "خانواده جود در این منطقه، در مزرعه‌ای کوچک در اوکلاهما زندگی می‌کردند."),
                    StoryParagraph("Tom Joad was the eldest son, a strong and proud young man who had just been released from prison.", "تام جود پسر بزرگ بود، مردی جوان، قوی و مغرور که تازه از زندان آزاد شده بود."),
                    StoryParagraph("He had been in prison for four years for killing a man in a fight, though he claimed it was self-defense.", "او چهار سال به خاطر کشتن مردی در دعوا در زندان بود، هرچند ادعا می‌کرد دفاع از خود بوده است."),
                    StoryParagraph("As Tom walked home along the dusty road, he met a former preacher named Jim Casy.", "وقتی تام در جاده غبارآلود به خانه می‌رفت، کشیش سابقی به نام جیم کیسی را ملاقات کرد."),
                    StoryParagraph("Jim Casy had lost his faith and no longer believed in preaching, but he was still a wise and kind man.", "جیم کیسی ایمانش را از دست داده بود و دیگر به موعظه باور نداشت، اما هنوز مردی دانا و مهربان بود."),
                    StoryParagraph("The two men walked together toward the Joad farm, talking about life, sin, and the human soul.", "آن دو مرد با هم به سمت مزرعه جود راه رفتند و درباره زندگی، گناه و روح انسان صحبت کردند."),
                    StoryParagraph("When they arrived, Tom found the farm abandoned and his family gone.", "وقتی رسیدند، تام متوجه شد مزرعه رها شده و خانواده‌اش رفته‌اند."),
                    StoryParagraph("A neighbor told him that the family had been forced off their land by the banks.", "همسایه‌ای به او گفت خانواده‌اش توسط بانک‌ها مجبور به ترک زمینشان شده‌اند."),
                    StoryParagraph("The banks and large companies had taken over the farms, using tractors to clear the land.", "بانک‌ها و شرکت‌های بزرگ مزارع را تصاحب کرده بودند و از تراکتور برای پاکسازی زمین استفاده می‌کردند."),
                    StoryParagraph("The small farmers could not compete and could not pay their debts, so they lost everything.", "کشاورزان کوچک نمی‌توانستند رقابت کنند و بدهی‌هایشان را بپردازند، پس همه چیز را از دست دادند."),
                    StoryParagraph("Tom found his family at his uncle's house, preparing to leave for California.", "تام خانواده‌اش را در خانه عمویش پیدا کرد، در حال آماده شدن برای رفتن به کالیفرنیا."),
