            StoryChapter(
                number = 5, title = "The Cotton Fields", titlePersian = "مزارع پنبه",
                paragraphs = listOf(
                    StoryParagraph("After the flood, the family found work on a large cotton farm in the San Joaquin Valley.", "بعد از سیل، خانواده کار در مزرعه پنبه بزرگی در دره سن خواکین پیدا کردند."),
                    StoryParagraph("The farm was owned by a wealthy company, and hundreds of workers picked cotton in the fields.", "مزرعه متعلق به شرکتی ثروتمند بود و صدها کارگر در مزارع پنبه می‌چیدند."),
                    StoryParagraph("The workers were paid by the pound, and the more they picked, the more money they earned.", "کارگران بر حسب پوند پول می‌گرفتند و هر چه بیشتر می‌چیدند، پول بیشتری درمی‌آوردند."),
                    StoryParagraph("But the cotton was scarce that year, and many workers could not pick enough to feed their families.", "اما پنبه آن سال کم بود و بسیاری از کارگران نمی‌توانستند به اندازه کافی بچینند تا خانواده‌شان را تغذیه کنند."),
                    StoryParagraph("The Joad family worked from sunrise to sunset, their hands bleeding from the sharp cotton bolls.", "خانواده جود از طلوع تا غروب کار می‌کردند و دستانشان از غوزه‌های تیز پنبه خونریزی می‌کرد."),
                    StoryParagraph("Ma Joad worked alongside her children, refusing to rest even when she was exhausted.", "مادر جود در کنار بچه‌هایش کار می‌کرد و حتی وقتی خسته بود از استراحت امتناع می‌کرد."),
                    StoryParagraph("Rose of Sharon was still weak from the loss of her baby, but she worked as hard as she could.", "رز آو شرون هنوز از فقدان نوزادش ضعیف بود، اما تا جایی که می‌توانست سخت کار می‌کرد."),
                    StoryParagraph("The family earned very little money, but they saved every penny they could.", "خانواده پول بسیار کمی درمی‌آوردند، اما هر پنی که می‌توانستند پس‌انداز می‌کردند."),
                    StoryParagraph("They dreamed of buying a small piece of land, a place where they could settle down and live in peace.", "آن‌ها رویای خرید قطعه زمین کوچکی را داشتند، جایی که بتوانند ساکن شوند و در آرامش زندگی کنند."),
                    StoryParagraph("But deep down, they knew that their dream was probably impossible.", "اما در اعماق وجودشان، می‌دانستند رویایشان احتمالاً غیرممکن است."),
                    StoryParagraph("One day, a man came to the camp and told the workers about a strike at a nearby farm.", "یک روز، مردی به کمپ آمد و به کارگران درباره اعتصابی در مزرعه‌ای نزدیک گفت."),
                    StoryParagraph("He said that the workers there were demanding higher wages and better conditions.", "او گفت کارگران آنجا خواستار دستمزد بالاتر و شرایط بهتر بودند."),
                    StoryParagraph("Some of the workers in the camp were interested, but others were afraid of losing their jobs.", "بعضی از کارگران کمپ علاقه‌مند شدند، اما دیگران می‌ترسیدند کارشان را از دست بدهند."),
                    StoryParagraph("The man warned them that the farmers would try to break the strike with violence.", "مرد هشدار داد که کشاورزان تلاش می‌کنند اعتصاب را با خشونت بشکنند."),
                    StoryParagraph("He said that the workers had to unite if they wanted to win their rights.", "او گفت کارگران باید متحد شوند اگر می‌خواهند حقوقشان را به دست آورند."),
                    StoryParagraph("Ma Joad listened carefully, and she began to understand the power of unity.", "مادر جود با دقت گوش داد و شروع به درک قدرت اتحاد کرد."),
                    StoryParagraph("She remembered Tom's words, that he would be with the people wherever they fought for justice.", "او کلمات تام را به یاد آورد، که گفت با مردم خواهد بود هر جا برای عدالت بجنگند."),
                    StoryParagraph("The family decided to stay out of the strike, because they needed the work too much.", "خانواده تصمیم گرفتند از اعتصاب دور بمانند، چون خیلی به کار نیاز داشتند."),
                    StoryParagraph("But they sympathized with the strikers, and they helped them in secret ways.", "اما با اعتصاب‌کنندگان همدلی کردند و مخفیانه به آن‌ها کمک کردند."),
                    StoryParagraph("One night, the police came to the camp and arrested several workers for organizing the strike.", "یک شب، پلیس به کمپ آمد و چندین کارگر را به خاطر سازماندهی اعتصاب دستگیر کرد."),
                    StoryParagraph("The workers were beaten and taken away, and no one knew where they were taken.", "کارگران کتک خوردند و برده شدند و هیچ‌کس نمی‌دانست کجا برده شدند."),
                    StoryParagraph("The family was terrified, and they realized how dangerous their situation was.", "خانواده وحشت کردند و فهمیدند وضعیتشان چقدر خطرناک است."),
                    StoryParagraph("They decided to leave the camp before something worse happened to them.", "تصمیم گرفتند قبل از اینکه اتفاق بدتری برایشان بیفتد کمپ را ترک کنند."),
                    StoryParagraph("They packed their few belongings and moved on again, looking for a safer place.", "وسایل اندکشان را جمع کردند و دوباره حرکت کردند و دنبال جای امن‌تری گشتند."),
                    StoryParagraph("They found another farm where they could work, but the conditions were even worse than before.", "مزرعه دیگری پیدا کردند که می‌توانستند در آن کار کنند، اما شرایط حتی بدتر از قبل بود."),
                    StoryParagraph("The farmer was cruel and dishonest, and he cheated the workers out of their wages.", "کشاورز بی‌رحم و ناصادق بود و کارگران را از دستمزدشان محروم می‌کرد."),
                    StoryParagraph("The workers complained, but the farmer threatened to call the police and have them arrested.", "کارگران شکایت کردند، اما کشاورز تهدید کرد پلیس را خبر می‌کند و دستگیرشان می‌کند."),
                    StoryParagraph("The family was trapped, because they had no money to leave and no place to go.", "خانواده گرفتار شدند، چون پولی برای رفتن و جایی برای رفتن نداشتند."),
                    StoryParagraph("They worked for weeks without pay, hoping that things would get better.", "هفته‌ها بدون دستمزد کار کردند و امیدوار بودند اوضاع بهتر شود."),
                    StoryParagraph("But things only got worse, and the family became more and more desperate.", "اما اوضاع فقط بدتر شد و خانواده بیشتر و بیشتر درمانده شد."),
                    StoryParagraph("One day, a group of workers decided to confront the farmer and demand their wages.", "یک روز، گروهی از کارگران تصمیم گرفتند با کشاورز روبرو شوند و دستمزدشان را طلب کنند."),
                    StoryParagraph("The farmer called the police, and a violent fight broke out between the workers and the police.", "کشاورز پلیس را خبر کرد و دعوای خشونت‌باری بین کارگران و پلیس درگرفت."),
                    StoryParagraph("Several workers were injured, and some were arrested and taken away.", "چندین کارگر مجروح شدند و بعضی دستگیر و برده شدند."),
                    StoryParagraph("The Joad family managed to escape in the chaos, but they were terrified and shaken.", "خانواده جود موفق شدند در هرج و مرج فرار کنند، اما ترسیده و متزلزل بودند."),
                    StoryParagraph("They realized that they could not trust anyone, not the farmers, not the police, not the government.", "آن‌ها فهمیدند نمی‌توانند به هیچ‌کس اعتماد کنند، نه کشاورزان، نه پلیس، نه دولت."),
                    StoryParagraph("The only people they could trust were other poor workers like themselves.", "تنها افرادی که می‌توانستند به آن‌ها اعتماد کنند، کارگران فقیر دیگری مثل خودشان بودند."),
                    StoryParagraph("And so they learned to rely on each other, and to share whatever they had.", "و اینگونه یاد گرفتند به یکدیگر تکیه کنند و هر چه دارند را تقسیم کنند."),
                    StoryParagraph("They found a small camp of workers who had also been cheated and abused.", "آن‌ها کمپ کوچکی از کارگران پیدا کردند که آن‌ها هم فریب خورده و مورد آزار قرار گرفته بودند."),
                    StoryParagraph("Together, they formed a community, a place where they could help each other survive.", "با هم، جامعه‌ای تشکیل دادند، جایی که می‌توانستند به هم کمک کنند تا زنده بمانند."),
                    StoryParagraph("Ma Joad became a leader in this community, and she was respected for her strength and wisdom.", "مادر جود رهبری در این جامعه شد و به خاطر قدرتش و خردش مورد احترام بود."),
                    StoryParagraph("She said that the people had to stick together, because alone they were weak, but together they were strong.", "او گفت مردم باید با هم بمانند، چون تنها ضعیف بودند، اما با هم قوی بودند."),
                    StoryParagraph("The family finally found a place where they could rest and feel safe, at least for a little while.", "خانواده بالاخره جایی پیدا کردند که می‌توانستند استراحت کنند و احساس امنیت کنند، حداقل برای مدتی."),
                    StoryParagraph("But they knew that their struggle was far from over, and that more challenges awaited them.", "اما می‌دانستند مبارزه‌شان هنوز تمام نشده و چالش‌های بیشتری در انتظارشان است."),
                    StoryParagraph("And so they prepared themselves for whatever was coming, with courage and with hope.", "و اینگونه خود را برای هر چه می‌آمد آماده کردند، با شجاعت و امید.")
                )
            ),
            StoryChapter(
                number = 6, title = "The End of the Road", titlePersian = "پایان راه",
                paragraphs = listOf(
                    StoryParagraph("The winter passed slowly, and the family survived on very little food and very little hope.", "زمستان به آرامی گذشت و خانواده با غذای بسیار کم و امید بسیار کم زنده ماندند."),
                    StoryParagraph("The community they had joined was strong, but it was also poor and struggling.", "جامعه‌ای که به آن پیوسته بودند قوی بود، اما فقیر و در حال تلاش هم بود."),
                    StoryParagraph("The workers shared everything they had, and no one was left to starve alone.", "کارگران هر چه داشتند تقسیم می‌کردند و هیچ‌کس تنها گرسنه نمی‌ماند."),
                    StoryParagraph("But there was never enough, and many people, especially children and old people, became sick.", "اما هرگز کافی نبود و بسیاری از مردم، به ویژه کودکان و سالمندان، بیمار شدند."),
                    StoryParagraph("Ma Joad worked day and night to help the sick, and she became a kind of nurse for the community.", "مادر جود شبانه‌روز کار کرد تا به بیماران کمک کند و نوعی پرستار برای جامعه شد."),
                    StoryParagraph("She had no medicine and no proper tools, but she used her knowledge and her love to heal people.", "او دارو و ابزار مناسب نداشت، اما از دانش و عشقش برای شفای مردم استفاده می‌کرد."),
                    StoryParagraph("Rose of Sharon also helped, and she began to recover from the loss of her baby.", "رز آو شرون هم کمک کرد و شروع به بهبودی از فقدان نوزادش کرد."),
                    StoryParagraph("She became stronger and more confident, and she began to think about the future again.", "او قوی‌تر و مطمئن‌تر شد و دوباره شروع به فکر کردن درباره آینده کرد."),
                    StoryParagraph("One day, a letter arrived from Tom, sent secretly through a friend.", "یک روز، نامه‌ای از تام رسید که مخفیانه از طریق دوستی فرستاده شده بود."),
                    StoryParagraph("He wrote that he was safe and that he was working with other people who were fighting for justice.", "او نوشت که در امان است و با افراد دیگری که برای عدالت می‌جنگند کار می‌کند."),
                    StoryParagraph("He said that he missed his family very much and that he thought about them every day.", "او گفت خیلی دلتنگ خانواده‌اش است و هر روز به آن‌ها فکر می‌کند."),
                    StoryParagraph("Ma Joad cried when she read the letter, but she was also proud of her son.", "مادر جود وقتی نامه را خواند گریه کرد، اما به پسرش هم افتخار کرد."),
                    StoryParagraph("She wrote back to him, telling him that the family was safe and that they loved him.", "او به او جواب نوشت و گفت خانواده در امان است و دوستش دارند."),
                    StoryParagraph("She told him to keep fighting, because the world needed people like him.", "او به او گفت به جنگیدن ادامه دهد، چون دنیا به افرادی مثل او نیاز دارد."),
                    StoryParagraph("The family continued to work when they could, and to help others when they could not.", "خانواده به کار کردن ادامه دادند وقتی می‌توانستند و به کمک به دیگران وقتی نمی‌توانستند."),
                    StoryParagraph("Spring came, and with it came new hope, because the fields began to turn green again.", "بهار آمد و با آن امید تازه آمد، چون مزارع دوباره سبز شدند."),
                    StoryParagraph("The workers found more work, and they began to earn a little more money.", "کارگران کار بیشتری پیدا کردند و شروع به درآمد کمی بیشتر کردند."),
                    StoryParagraph("The Joad family saved their money, and they began to dream again about buying a small farm.", "خانواده جود پولشان را پس‌انداز کردند و دوباره شروع به رویای خرید مزرعه کوچکی کردند."),
                    StoryParagraph("But they knew that their dream was fragile and that it could be destroyed at any moment.", "اما می‌دانستند رویایشان شکننده است و هر لحظه می‌تواند نابود شود."),
                    StoryParagraph("One day, a man came to the camp and told them about a place where workers could buy their own land.", "یک روز، مردی به کمپ آمد و به آن‌ها درباره جایی گفت که کارگران می‌توانستند زمین خودشان را بخرند."),
                    StoryParagraph("It was a government program to help poor farmers and workers build a better life.", "برنامه دولتی بود برای کمک به کشاورزان و کارگران فقیر برای ساختن زندگی بهتر."),
                    StoryParagraph("The family was excited and hopeful, and they decided to go there and see for themselves.", "خانواده هیجان‌زده و امیدوار شدند و تصمیم گرفتند بروند و خودشان ببینند."),
                    StoryParagraph("They traveled for many days, and finally they arrived at the place, which was called a resettlement camp.", "روزها سفر کردند و بالاخره به جایی رسیدند که کمپ اسکان مجدد نام داشت."),
                    StoryParagraph("The camp was clean and organized, and the people there were friendly and helpful.", "کمپ تمیز و سازمان‌یافته بود و مردم آنجا دوستانه و کمک‌کننده بودند."),
                    StoryParagraph("Each family was given a small house with a garden, and they could grow their own food.", "به هر خانواده خانه کوچکی با باغ داده شد و می‌توانستند غذای خودشان را پرورش دهند."),
                    StoryParagraph("The Joad family was given a house, and for the first time in years, they had a place to call home.", "خانواده جود خانه‌ای دریافت کردند و برای اولین بار در سال‌ها، جایی برای خانه داشتند."),
                    StoryParagraph("Ma Joad cried with joy when she saw the house, because it was clean and warm and safe.", "مادر جود وقتی خانه را دید از خوشحالی گریه کرد، چون تمیز و گرم و امن بود."),
                    StoryParagraph("The children ran in the garden, and the adults sat and talked about the future.", "بچه‌ها در باغ دویدند و بزرگترها نشستند و درباره آینده صحبت کردند."),
                    StoryParagraph("It was a new beginning for the family, a chance to start over and build a better life.", "شروع تازه‌ای برای خانواده بود، فرصتی برای شروع دوباره و ساختن زندگی بهتر."),
                    StoryParagraph("But they did not forget their past, or the people they had left behind.", "اما گذشته‌شان را فراموش نکردند، یا افرادی که پشت سر گذاشته بودند."),
                    StoryParagraph("They remembered Tom, and Jim Casy, and all the workers who had suffered and died.", "تام را به یاد آوردند، و جیم کیسی، و همه کارگرانی که رنج کشیده و مرده بودند."),
                    StoryParagraph("They knew that their happiness was built on the suffering of others, and they felt a deep responsibility.", "می‌دانستند خوشبختی‌شان بر رنج دیگران ساخته شده و احساس مسئولیت عمیقی کردند."),
                    StoryParagraph("Ma Joad said that they had to help others, just as others had helped them.", "مادر جود گفت باید به دیگران کمک کنند، همانطور که دیگران به آن‌ها کمک کرده بودند."),
                    StoryParagraph("She said that the people were one family, and that they had to take care of each other.", "او گفت مردم یک خانواده هستند و باید مراقب هم باشند."),
                    StoryParagraph("And so the Joad family began their new life, with gratitude and with hope.", "و اینگونه خانواده جود زندگی جدیدشان را با سپاسگزاری و امید آغاز کردند."),
                    StoryParagraph("They worked hard, and they helped their neighbors, and they built a community of love and trust.", "سخت کار کردند، به همسایگانشان کمک کردند و جامعه‌ای از عشق و اعتماد ساختند."),
                    StoryParagraph("Rose of Sharon found new purpose in helping other women and children.", "رز آو شرون هدف جدیدی در کمک به زنان و کودکان دیگر یافت."),
                    StoryParagraph("She became a leader in the community, just like her mother.", "او مثل مادرش رهبری در جامعه شد."),
                    StoryParagraph("And Ma Joad watched her daughter with pride, knowing that the family would survive.", "و مادر جود با افتخار دخترش را تماشا کرد و می‌دانست خانواده زنده می‌ماند."),
                    StoryParagraph("The story of the Joad family is a story of suffering, but it is also a story of hope.", "داستان خانواده جود، داستانی از رنج است، اما داستانی از امید هم هست."),
                    StoryParagraph("It is a story of people who refused to be broken, who kept fighting even when everything was against them.", "داستانی است از افرادی که از شکستن امتناع کردند و حتی وقتی همه چیز علیه‌شان بود به جنگیدن ادامه دادند."),
                    StoryParagraph("And it is a story that reminds us of the power of love, of family, and of the human spirit.", "و داستانی است که ما را به یاد قدرت عشق، خانواده و روح انسانی می‌اندازد."),
                    StoryParagraph("And so the grapes of wrath continue to grow, waiting for the harvest of justice.", "و اینگونه خوشه‌های خشم همچنان رشد می‌کنند و منتظر برداشت عدالت هستند."),
                    StoryParagraph("But until that day comes, the people will keep fighting, keep hoping, and keep living.", "اما تا آن روز که بیاید، مردم به جنگیدن، امیدوار بودن و زندگی کردن ادامه خواهند داد.")
                )
            )
        )
    )

    // ─────────────── ۴۵: بلندی‌های بادگیر ───────────────
    private fun story45() = StoryContent(
        storyId = "int_wuthering_heights_int",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Visitor", titlePersian = "مهمان",
                paragraphs = listOf(
                    StoryParagraph("Mr. Lockwood was a gentleman from London who had come to the countryside to rest.", "آقای لاک‌وود جنتلمنی از لندن بود که برای استراحت به حومه شهر آمده بود."),
                    StoryParagraph("He rented a house called Thrushcross Grange, a beautiful estate in the moors.", "او خانه‌ای به نام ثراش‌کراس گرینج اجاره کرد، ملکی زیبا در دشت‌های خلنگ‌زار."),
                    StoryParagraph("His landlord was a strange and gloomy man named Mr. Heathcliff.", "صاحب‌خانه‌اش مردی عجیب و غمگین به نام آقای هیتکلیف بود."),
                    StoryParagraph("Heathcliff lived at Wuthering Heights, an old farmhouse on the hill, exposed to the wind and storms.", "هیتکلیف در بلندی‌های بادگیر زندگی می‌کرد، خانه‌ای قدیمی روی تپه که در معرض باد و طوفان بود."),
                    StoryParagraph("One day, Lockwood decided to visit his landlord at Wuthering Heights.", "یک روز، لاک‌وود تصمیم گرفت از صاحب‌خانه‌اش در بلندی‌های بادگیر دیدن کند."),
                    StoryParagraph("The house was cold and unwelcoming, and the people inside were rude and unfriendly.", "خانه سرد و ناخوشایند بود و افراد داخل بی‌ادب و غیردوستانه بودند."),
                    StoryParagraph("He met a beautiful young woman named Catherine, who was cold and distant.", "او زن جوان زیبایی به نام کاترین ملاقات کرد که سرد و دور بود."),
                    StoryParagraph("He also met a young man named Hareton, who was rough and uneducated.", "او همچنین مرد جوانی به نام هارتون ملاقات کرد که خشن و بی‌سواد بود."),
                    StoryParagraph("There was also a servant named Joseph, an old man who was deeply religious and very unpleasant.", "خدمتکاری هم به نام جوزف بود، پیرمردی که به شدت مذهبی و بسیار ناخوشایند بود."),
                    StoryParagraph("Heathcliff himself was dark and mysterious, with a strange and dangerous look in his eyes.", "خود هیتکلیف تاریک و مرموز بود و نگاهی عجیب و خطرناک در چشمانش داشت."),
                    StoryParagraph("Lockwood did not understand the relationships between these people, and he was confused.", "لاک‌وود روابط بین این افراد را نمی‌فهمید و گیج شده بود."),
                    StoryParagraph("That night, a terrible snowstorm began, and Lockwood was forced to stay at Wuthering Heights.", "آن شب، طوفان برفی وحشتناکی آغاز شد و لاک‌وود مجبور شد در بلندی‌های بادگیر بماند."),
                    StoryParagraph("He was given a room that was said to be haunted, and he had a terrible nightmare.", "اتاقی به او داده شد که می‌گفتند جن‌زده است و کابوس وحشتناکی دید."),
                    StoryParagraph("In his dream, a ghostly child appeared at the window and begged to be let in.", "در خوابش، کودک روح‌مانندی در پنجره ظاهر شد و التماس کرد که او را به داخل راه دهند."),
                    StoryParagraph("The child said her name was Catherine Linton, and she had been lost for twenty years.", "کودک گفت نامش کاترین لینتون است و بیست سال گم شده است."),
                    StoryParagraph("Lockwood screamed in terror, and Heathcliff came running into the room.", "لاک‌وود از وحشت فریاد زد و هیتکلیف دوان‌دوان به اتاق آمد."),
                    StoryParagraph("Heathcliff opened the window and called out to the ghost, begging her to come back.", "هیتکلیف پنجره را باز کرد و روح را صدا زد و التماس کرد برگردد."),
                    StoryParagraph("But there was no answer, only the sound of the wind and the snow.", "اما جوابی نیامد، فقط صدای باد و برف بود."),
                    StoryParagraph("The next morning, Lockwood left Wuthering Heights and returned to Thrushcross Grange.", "صبح روز بعد، لاک‌وود بلندی‌های بادگیر را ترک کرد و به ثراش‌کراس گرینج بازگشت."),
                    StoryParagraph("He asked his housekeeper, Mrs. Dean, to tell him the story of Heathcliff and Catherine.", "او از خانه‌دارش، خانم دین، خواست داستان هیتکلیف و کاترین را برایش تعریف کند."),
                    StoryParagraph("Mrs. Dean had lived in the area all her life, and she knew all the secrets of the two families.", "خانم دین تمام عمرش در آن منطقه زندگی کرده بود و همه رازهای دو خانواده را می‌دانست."),
                    StoryParagraph("She began to tell him the story, a story of love, hate, and revenge that had lasted for generations.", "او شروع کرد به تعریف داستان، داستانی از عشق، نفرت و انتقام که نسل‌ها ادامه داشته بود."),
                    StoryParagraph("Many years ago, Wuthering Heights was owned by Mr. Earnshaw, a kind and generous man.", "سال‌ها پیش، بلندی‌های بادگیر متعلق به آقای ارنشاو بود، مردی مهربان و بخشنده."),
                    StoryParagraph("He had two children, a son named Hindley and a daughter named Catherine.", "او دو فرزند داشت، پسری به نام هیندلی و دختری به نام کاترین."),
                    StoryParagraph("One day, Mr. Earnshaw went to the city and returned with a strange, dark-eyed boy.", "یک روز، آقای ارنشاو به شهر رفت و با پسر عجیبی با چشمان تیره بازگشت."),
                    StoryParagraph("The boy was an orphan, and he had been living on the streets, starving and alone.", "پسر یتیم بود و در خیابان‌ها زندگی می‌کرد، گرسنه و تنها."),
                    StoryParagraph("Mr. Earnshaw named him Heathcliff, and he raised him as his own son.", "آقای ارنشاو او را هیتکلیف نامید و مثل پسر خودش بزرگ کرد."),
                    StoryParagraph("Hindley was jealous of Heathcliff and treated him cruelly, but Catherine loved him deeply.", "هیندلی به هیتکلیف حسادت می‌کرد و با او ظالمانه رفتار می‌کرد، اما کاترین عمیقاً دوستش داشت."),
                    StoryParagraph("Catherine and Heathcliff became inseparable, and they spent their days playing on the moors.", "کاترین و هیتکلیف جدانشدنی شدند و روزهایشان را در دشت‌های خلنگ‌زار بازی می‌کردند."),
                    StoryParagraph("They were wild and free, and they loved each other with a love that was stronger than friendship.", "آن‌ها وحشی و آزاد بودند و یکدیگر را با عشقی قوی‌تر از دوستی دوست داشتند."),
                    StoryParagraph("But their happiness did not last, because Mr. Earnshaw became sick and died.", "اما خوشبختی‌شان دوام نیاورد، چون آقای ارنشاو بیمار شد و مرد."),
                    StoryParagraph("After his death, Hindley became the master of Wuthering Heights and treated Heathcliff like a servant.", "بعد از مرگش، هیندلی ارباب بلندی‌های بادگیر شد و با هیتکلیف مثل خدمتکار رفتار می‌کرد."),
                    StoryParagraph("Heathcliff was forced to work in the fields and was not allowed to study or be with Catherine.", "هیتکلیف مجبور شد در مزارع کار کند و اجازه نداشت درس بخواند یا با کاترین باشد."),
                    StoryParagraph("But Catherine and Heathcliff continued to meet in secret, and their love grew stronger.", "اما کاترین و هیتکلیف مخفیانه ملاقات می‌کردند و عشقشان قوی‌تر می‌شد."),
                    StoryParagraph("One day, Catherine was bitten by a dog at Thrushcross Grange, and she was taken in by the Linton family.", "یک روز، کاترین توسط سگی در ثراش‌کراس گرینج گاز گرفته شد و خانواده لینتون او را پذیرفتند."),
                    StoryParagraph("The Lintons were rich and educated, and they taught Catherine how to be a proper lady.", "لینتون‌ها ثروتمند و تحصیل‌کرده بودند و به کاترین یاد دادند چگونه یک بانوی محترم باشد."),
                    StoryParagraph("When Catherine returned to Wuthering Heights, she was different, and she began to look down on Heathcliff.", "وقتی کاترین به بلندی‌های بادگیر برگشت، متفاوت شده بود و شروع کرد به تحقیر هیتکلیف."),
                    StoryParagraph("This hurt Heathcliff deeply, but he still loved her more than anything in the world.", "این هیتکلیف را عمیقاً زخمی کرد، اما او هنوز بیشتر از هر چیزی در دنیا دوستش داشت."),
                    StoryParagraph("Soon, Edgar Linton, the son of the Linton family, fell in love with Catherine and asked her to marry him.", "به زودی، ادگار لینتون، پسر خانواده لینتون، عاشق کاترین شد و از او خواست با او ازدواج کند."),
                    StoryParagraph("Catherine was torn between her love for Heathcliff and her desire for a wealthy, respectable life.", "کاترین بین عشقش به هیتکلیف و تمایلش به زندگی ثروتمند و محترم دو دل بود."),
                    StoryParagraph("She decided to marry Edgar, even though she knew it would break Heathcliff's heart.", "او تصمیم گرفت با ادگار ازدواج کند، حتی اگر می‌دانست قلب هیتکلیف را می‌شکند."),
                    StoryParagraph("When Heathcliff heard the news, he ran away from Wuthering Heights and disappeared for three years.", "وقتی هیتکلیف خبر را شنید، از بلندی‌های بادگیر فرار کرد و سه سال ناپدید شد."),
                    StoryParagraph("Catherine married Edgar and went to live at Thrushcross Grange, but she was never truly happy.", "کاترین با ادگار ازدواج کرد و به ثراش‌کراس گرینج رفت، اما هرگز واقعاً خوشحال نبود."),
                    StoryParagraph("She missed Heathcliff every day, and she felt that a part of her was missing.", "او هر روز دلتنگ هیتکلیف بود و احساس می‌کرد بخشی از وجودش گم شده است."),
                    StoryParagraph("And so the story of love and tragedy began, a story that would end in sorrow for everyone.", "و اینگونه داستان عشق و تراژدی آغاز شد، داستانی که برای همه به اندوه ختم می‌شد.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Return", titlePersian = "بازگشت",
                paragraphs = listOf(
                    StoryParagraph("After three years, Heathcliff returned to Wuthering Heights, but he was a changed man.", "بعد از سه سال، هیتکلیف به بلندی‌های بادگیر برگشت، اما مردی تغییر یافته بود."),
                    StoryParagraph("He was now rich and well-dressed, and he had a cold, hard look in his eyes.", "او حالا ثروتمند و خوش‌پوش بود و نگاهی سرد و سخت در چشمانش داشت."),
                    StoryParagraph("No one knew how he had made his fortune, but there were rumors of dark and dishonest dealings.", "هیچ‌کس نمی‌دانست ثروتش را از کجا آورده، اما شایعاتی از معاملات تاریک و ناصادقانه وجود داشت."),
                    StoryParagraph("Catherine was shocked and overjoyed to see him, but also frightened by his coldness.", "کاترین از دیدنش شوکه و خوشحال شد، اما از سردی‌اش هم ترسید."),
                    StoryParagraph("Heathcliff had returned with one purpose: to take revenge on everyone who had hurt him.", "هیتکلیف با یک هدف برگشته بود: انتقام از هر کسی که به او آسیب رسانده بود."),
                    StoryParagraph("He hated Hindley for treating him like a servant, and he hated Edgar for marrying Catherine.", "او از هیندلی به خاطر رفتار خدمتکارگونه متنفر بود و از ادگار به خاطر ازدواج با کاترین."),
                    StoryParagraph("He began to visit Wuthering Heights often, and he started gambling with Hindley.", "او شروع کرد به رفتن مکرر به بلندی‌های بادگیر و با هیندلی قمار می‌کرد."),
                    StoryParagraph("Hindley was already a drunkard, and Heathcliff encouraged his drinking and gambling.", "هیندلی از قبل می‌گسار بود و هیتکلیف نوشیدن و قمارش را تشویق می‌کرد."),
                    StoryParagraph("Slowly, Heathcliff won all of Hindley's money and property, until Hindley was completely ruined.", "به آرامی، هیتکلیف تمام پول و دارایی هیندلی را برد، تا اینکه هیندلی کاملاً ورشکست شد."),
                    StoryParagraph("Heathcliff also began to court Isabella, Edgar's sister, even though he did not love her.", "هیتکلیف همچنین شروع به خواستگاری از ایزابلا، خواهر ادگار، کرد، حتی اگر دوستش نداشت."),
                    StoryParagraph("He only wanted to hurt Edgar, and marrying Isabella was a way to do that.", "او فقط می‌خواست ادگار را آزار دهد و ازدواج با ایزابلا راهی برای این کار بود."),
                    StoryParagraph("Catherine was furious and heartbroken when she heard about the marriage.", "کاترین وقتی درباره ازدواج شنید خشمگین و دلشکسته شد."),
                    StoryParagraph("She confronted Heathcliff and told him that he was cruel and selfish.", "او با هیتکلیف روبرو شد و به او گفت بی‌رحم و خودخواه است."),
                    StoryParagraph("Heathcliff replied that she had betrayed him first by marrying Edgar.", "هیتکلیف جواب داد که او اول با ازدواج با ادگار به او خیانت کرده است."),
                    StoryParagraph("Their argument was terrible, and Catherine became so upset that she fell ill.", "دعوایشان وحشتناک بود و کاترین آنقدر ناراحت شد که بیمار شد."),
                    StoryParagraph("She became feverish and delirious, and she was close to death.", "او تب کرد و هذیان گفت و نزدیک به مرگ بود."),
                    StoryParagraph("Edgar was desperate and did everything he could to save her, but nothing worked.", "ادگار درمانده شد و هر کاری می‌توانست برای نجاتش کرد، اما هیچ چیز کار نکرد."),
                    StoryParagraph("Heathcliff, meanwhile, married Isabella and took her to live at Wuthering Heights.", "هیتکلیف در همین حال با ایزابلا ازدواج کرد و او را به بلندی‌های بادگیر برد."),
                    StoryParagraph("Isabella was miserable there, because Heathcliff treated her cruelly and ignored her.", "ایزابلا آنجا بدبخت بود، چون هیتکلیف با او ظالمانه رفتار می‌کرد و نادیده‌اش می‌گرفت."),
                    StoryParagraph("She soon realized that she had made a terrible mistake in marrying him.", "او به زودی فهمید که در ازدواج با او اشتباه وحشتناکی کرده است."),
                    StoryParagraph("One night, Catherine gave birth to a baby girl, and then she died.", "یک شب، کاترین دختر کوچکی به دنیا آورد و بعد مرد."),
                    StoryParagraph("Her last words were of Heathcliff, and she died with his name on her lips.", "آخرین کلماتش درباره هیتکلیف بود و با نام او بر لب مرد."),
                    StoryParagraph("Heathcliff was devastated when he heard the news, and he cursed God and everyone around him.", "هیتکلیف وقتی خبر را شنید نابود شد و خدا و همه اطرافیانش را نفرین کرد."),
                    StoryParagraph("He begged Catherine's ghost to haunt him, to never leave him alone.", "او التماس کرد روح کاترین او را تسخیر کند، هرگز او را تنها نگذارد."),
                    StoryParagraph("From that day on, Heathcliff became even more cruel and bitter than before.", "از آن روز به بعد، هیتکلیف حتی بی‌رحم‌تر و تلخ‌تر از قبل شد."),
                    StoryParagraph("Isabella ran away from him and went to London, where she gave birth to a son named Linton.", "ایزابلا از او فرار کرد و به لندن رفت، جایی که پسری به نام لینتون به دنیا آورد."),
                    StoryParagraph("She never returned to Wuthering Heights, and she never saw Heathcliff again.", "او هرگز به بلندی‌های بادگیر برنگشت و هرگز هیتکلیف را دوباره ندید."),
                    StoryParagraph("Meanwhile, Edgar was left to raise his daughter, Catherine's child, all alone.", "در همین حال، ادگار ماند تا دخترش، فرزند کاترین، را تنها بزرگ کند."),
                    StoryParagraph("He named her Catherine, in memory of his beloved wife.", "او او را کاترین نامید، به یاد همسر محبوبش."),
                    StoryParagraph("Young Catherine grew up to be beautiful and kind, much like her mother.", "کاترین جوان زیبا و مهربان شد، بسیار شبیه مادرش."),
                    StoryParagraph("But Heathcliff had not forgotten his revenge, and he began to plan how to destroy the Linton family.", "اما هیتکلیف انتقامش را فراموش نکرده بود و شروع کرد به نقشه کشیدن برای نابودی خانواده لینتون."),
                    StoryParagraph("He forced his son Linton to come to Wuthering Heights, even though the boy was sick and weak.", "او پسرش لینتون را مجبور کرد به بلندی‌های بادگیر بیاید، حتی اگر پسر بیمار و ضعیف بود."),
                    StoryParagraph("He wanted Linton to marry young Catherine, so that he could inherit Thrushcross Grange.", "او می‌خواست لینتون با کاترین جوان ازدواج کند تا بتواند ثراش‌کراس گرینج را به ارث ببرد."),
                    StoryParagraph("Young Catherine was kept away from Wuthering Heights, but Heathcliff found a way to bring her there.", "کاترین جوان از بلندی‌های بادگیر دور نگه داشته می‌شد، اما هیتکلیف راهی پیدا کرد تا او را آنجا بیاورد."),
                    StoryParagraph("He locked her in the house and forced her to marry Linton, who was dying.", "او او را در خانه حبس کرد و مجبورش کرد با لینتون، که در حال مرگ بود، ازدواج کند."),
                    StoryParagraph("Edgar died soon after, and Heathcliff finally got what he wanted.", "ادگار کمی بعد مرد و هیتکلیف بالاخره به آنچه می‌خواست رسید."),
                    StoryParagraph("He now owned both Wuthering Heights and Thrushcross Grange, and he had destroyed all his enemies.", "او حالا مالک هر دو بلندی‌های بادگیر و ثراش‌کراس گرینج بود و همه دشمنانش را نابود کرده بود."),
                    StoryParagraph("But his revenge did not bring him peace, and he became more and more miserable every day.", "اما انتقامش برایش آرامش نیاورد و هر روز بیشتر و بیشتر بدبخت می‌شد."),
                    StoryParagraph("He started seeing Catherine's ghost everywhere, and he could not sleep or eat.", "او شروع کرد به دیدن روح کاترین همه‌جا و نمی‌توانست بخوابد یا غذا بخورد."),
                    StoryParagraph("He wandered the moors at night, calling out her name, begging her to return.", "او شب‌ها در دشت‌های خلنگ‌زار سرگردان بود، نامش را صدا می‌زد، التماس می‌کرد برگردد."),
                    StoryParagraph("And so his life became a living hell, a hell that he had created for himself.", "و اینگونه زندگی‌اش به جهنمی زنده تبدیل شد، جهنمی که خودش برای خودش ساخته بود."),
                    StoryParagraph("He had gotten his revenge, but he had lost everything that truly mattered.", "او انتقامش را گرفته بود، اما هر چیزی که واقعاً مهم بود را از دست داده بود."),
                    StoryParagraph("And the story of Wuthering Heights continued, a story of love that had turned into hate.", "و داستان بلندی‌های بادگیر ادامه یافت، داستانی از عشقی که به نفرت تبدیل شده بود.")
                )
            ),
            StoryChapter(
                number = 3, title = "The Revenge", titlePersian = "انتقام",
                paragraphs = listOf(
                    StoryParagraph("After Catherine's death, Heathcliff became a man consumed by grief and hatred.", "بعد از مرگ کاترین، هیتکلیف مردی شد که غم و نفرت او را فرا گرفته بود."),
                    StoryParagraph("He hated everyone who had ever hurt him or stood in his way, and he wanted them all to suffer.", "او از هر کسی که به او آسیب رسانده یا سر راهش ایستاده بود متنفر بود و می‌خواست همه رنج ببرند."),
                    StoryParagraph("His first target was Hindley Earnshaw, the man who had treated him like a servant.", "اولین هدفش هیندلی ارنشاو بود، مردی که با او مثل خدمتکار رفتار کرده بود."),
                    StoryParagraph("Hindley had become a drunk and a gambler after his wife's death, and he was easy to destroy.", "هیندلی بعد از مرگ همسرش به یک می‌خوار و قمارباز تبدیل شده بود و نابود کردنش آسان بود."),
                    StoryParagraph("Heathcliff lent him money for his gambling, and slowly, he took control of Wuthering Heights.", "هیتکلیف برای قمار به او پول قرض داد و به آرامی، کنترل بلندی‌های بادگیر را به دست گرفت."),
                    StoryParagraph("When Hindley died, the house belonged to Heathcliff, and Hindley's son Hareton was left with nothing.", "وقتی هیندلی مرد، خانه متعلق به هیتکلیف شد و پسرش هیرتون با هیچ چیز رها شد."),
                    StoryParagraph("Heathcliff raised Hareton as a rough and uneducated servant, just as he himself had been raised.", "هیتکلیف هیرتون را مثل خدمتکاری خشن و بی‌سواد بزرگ کرد، همانطور که خودش بزرگ شده بود."),
                    StoryParagraph("He wanted Hareton to suffer the same humiliation that he had suffered as a boy.", "او می‌خواست هیرتون همان تحقیری را تحمل کند که خودش در کودکی تحمل کرده بود."),
                    StoryParagraph("But strangely, Heathcliff also loved Hareton in his own twisted way, because the boy reminded him of Catherine.", "اما به شکلی عجیب، هیتکلیف هیرتون را هم به روش پیچیده خودش دوست داشت، چون پسر او را به یاد کاترین می‌انداخت."),
                    StoryParagraph("His second target was the Linton family, especially Edgar, the man Catherine had married.", "هدف دومش خانواده لینتون بود، به ویژه ادگار، مردی که کاترین با او ازدواج کرده بود."),
                    StoryParagraph("Edgar had a daughter named Cathy, who was born just before Catherine died.", "ادگار دختری به نام کتی داشت که درست قبل از مرگ کاترین به دنیا آمد."),
                    StoryParagraph("Cathy grew up to be beautiful and kind, much like her mother, but she was also headstrong and curious.", "کتی زیبا و مهربان بزرگ شد، بسیار شبیه مادرش، اما لجباز و کنجکاو هم بود."),
                    StoryParagraph("She was not allowed to leave Thrushcross Grange, because her father was afraid of Heathcliff.", "اجازه نداشت ثراش‌کراس گرینج را ترک کند، چون پدرش از هیتکلیف می‌ترسید."),
                    StoryParagraph("But one day, when she was exploring the moors, she met Hareton and Heathcliff by accident.", "اما یک روز، وقتی در دشت‌ها کاوش می‌کرد، تصادفاً با هیرتون و هیتکلیف ملاقات کرد."),
                    StoryParagraph("Heathcliff realized who she was, and he saw a chance to take his revenge on Edgar through his daughter.", "هیتکلیف فهمید او کیست و فرصتی دید تا از طریق دخترش از ادگار انتقام بگیرد."),
                    StoryParagraph("He invited Cathy to Wuthering Heights, and he treated her kindly, hiding his true intentions.", "او کتی را به بلندی‌های بادگیر دعوت کرد و با او مهربانانه رفتار کرد و نیات واقعی‌اش را پنهان کرد."),
                    StoryParagraph("Cathy was fascinated by Heathcliff and by the strange, dark house on the hill.", "کتی شیفته هیتکلیف و خانه عجیب و تاریک روی تپه شد."),
                    StoryParagraph("She also became friends with Hareton, although she thought he was rough and uneducated.", "او با هیرتون هم دوست شد، هرچند فکر می‌کرد او خشن و بی‌سواد است."),
                    StoryParagraph("Meanwhile, Heathcliff's son Linton, who was weak and sickly, had been sent to live at Wuthering Heights.", "در همین حال، پسر هیتکلیف، لینتون، که ضعیف و بیمار بود، به بلندی‌های بادگیر فرستاده شد تا زندگی کند."),
                    StoryParagraph("Linton was a pale, selfish boy, and he was terrified of his father, who treated him cruelly.", "لینتون پسری رنگ‌پریده و خودخواه بود و از پدرش که با او ظالمانه رفتار می‌کرد وحشت داشت."),
                    StoryParagraph("Heathcliff forced Linton to befriend Cathy, because he wanted them to marry.", "هیتکلیف لینتون را مجبور کرد با کتی دوست شود، چون می‌خواست آن‌ها ازدواج کنند."),
                    StoryParagraph("If Cathy married Linton, then Heathcliff would control both Thrushcross Grange and Wuthering Heights.", "اگر کتی با لینتون ازدواج می‌کرد، هیتکلیف هم ثراش‌کراس گرینج و هم بلندی‌های بادگیر را کنترل می‌کرد."),
                    StoryParagraph("Edgar was horrified when he learned about this plan, and he forbade Cathy from seeing Linton again.", "ادگار وقتی این نقشه را فهمید وحشت کرد و کتی را از دیدن دوباره لینتون منع کرد."),
                    StoryParagraph("But Cathy was young and foolish, and she continued to meet Linton in secret.", "اما کتی جوان و احمق بود و مخفیانه به ملاقات لینتون ادامه داد."),
                    StoryParagraph("Linton was kind to her in his own weak way, and Cathy began to feel sorry for him.", "لینتون به روش ضعیف خودش با او مهربان بود و کتی شروع کرد به دلسوزی برایش."),
                    StoryParagraph("Heathcliff used this sympathy to trap Cathy, and eventually, he forced her to marry Linton.", "هیتکلیف از این دلسوزی برای به دام انداختن کتی استفاده کرد و در نهایت، او را مجبور به ازدواج با لینتون کرد."),
                    StoryParagraph("Edgar was heartbroken, and he died soon after, leaving Cathy alone and helpless.", "ادگار دلشکسته شد و کمی بعد مرد و کتی را تنها و درمانده گذاشت."),
                    StoryParagraph("Now Heathcliff controlled everything: Wuthering Heights, Thrushcross Grange, and both families.", "حالا هیتکلیف همه چیز را کنترل می‌کرد: بلندی‌های بادگیر، ثراش‌کراس گرینج و هر دو خانواده."),
                    StoryParagraph("But he was not happy, because he still could not forget Catherine, and his grief consumed him.", "اما خوشحال نبود، چون هنوز نمی‌توانست کاترین را فراموش کند و غمش او را می‌خورد."),
                    StoryParagraph("He saw Catherine's ghost everywhere, and he began to long for his own death.", "او روح کاترین را همه‌جا می‌دید و شروع کرد به آرزوی مرگ خودش."),
                    StoryParagraph("Linton died soon after his marriage to Cathy, weak and miserable to the end.", "لینتون کمی بعد از ازدواجش با کتی مرد، ضعیف و بدبخت تا آخرین لحظه."),
                    StoryParagraph("Cathy was left alone at Wuthering Heights, where she was treated coldly by Heathcliff.", "کتی تنها در بلندی‌های بادگیر رها شد، جایی که هیتکلیف با او سرد رفتار می‌کرد."),
                    StoryParagraph("But she was not completely alone, because Hareton was still there, and he had always loved her.", "اما کاملاً تنها نبود، چون هیرتون هنوز آنجا بود و همیشه دوستش داشت."),
                    StoryParagraph("At first, Cathy was cruel to Hareton, because she thought he was beneath her.", "اول، کتی با هیرتون بی‌رحم بود، چون فکر می‌کرد او پایین‌تر از اوست."),
                    StoryParagraph("But slowly, she began to see the kindness in his heart, and she began to love him.", "اما به آرامی، شروع کرد به دیدن مهربانی در قلبش و شروع کرد به عشق ورزیدن به او."),
                    StoryParagraph("Heathcliff watched their growing love with a mixture of anger and sadness.", "هیتکلیف عشق در حال رشد آن‌ها را با ترکیبی از خشم و اندوه تماشا کرد."),
                    StoryParagraph("He saw in them a reflection of himself and Catherine, and it both tormented and comforted him.", "او در آن‌ها بازتابی از خودش و کاترین را دید و هم عذابش داد و هم آرامش بخشید."),
                    StoryParagraph("Slowly, Heathcliff began to lose his desire for revenge, because he was too tired and broken.", "به آرامی، هیتکلیف شروع کرد به از دست دادن میل به انتقام، چون خیلی خسته و شکسته بود."),
                    StoryParagraph("He stopped eating and sleeping, and he spent his nights walking on the moors, calling Catherine's name.", "او از خوردن و خوابیدن دست کشید و شب‌ها را در دشت‌ها قدم می‌زد و نام کاترین را صدا می‌زد."),
                    StoryParagraph("One morning, he was found dead in his room, with a strange smile on his face.", "یک صبح، در اتاقش مرده پیدا شد، با لبخندی عجیب روی صورتش."),
                    StoryParagraph("Some said that he had finally found peace, and that he was reunited with Catherine at last.", "بعضی گفتند بالاخره آرامش یافته و در نهایت با کاترین متحد شده است."),
                    StoryParagraph("After his death, Cathy and Hareton were married, and they moved to Thrushcross Grange.", "بعد از مرگش، کتی و هیرتون ازدواج کردند و به ثراش‌کراس گرینج رفتند."),
                    StoryParagraph("They were happy together, and their love was gentle and kind, unlike the love of Heathcliff and Catherine.", "آن‌ها با هم خوشحال بودند و عشقشان لطیف و مهربان بود، برخلاف عشق هیتکلیف و کاترین."),
                    StoryParagraph("And so the story of Wuthering Heights ended, but the ghosts of the past still haunted the moors.", "و اینگونه داستان بلندی‌های بادگیر پایان یافت، اما ارواح گذشته هنوز در دشت‌ها پرسه می‌زدند."),
                    StoryParagraph("Some say that the ghosts of Heathcliff and Catherine still walk together on the wild moors.", "بعضی می‌گویند ارواح هیتکلیف و کاترین هنوز با هم در دشت‌های وحشی قدم می‌زنند."),
                    StoryParagraph("And that their love, which had been so destructive in life, had finally found peace in death.", "و عشقشان، که در زندگی اینقدر مخرب بود، در نهایت در مرگ آرامش یافته است."),
                    StoryParagraph("That is the story of Wuthering Heights, a story of love, hate, revenge, and redemption.", "این داستان بلندی‌های بادگیر است، داستانی از عشق، نفرت، انتقام و رستگاری.")
                )
            ),
            StoryChapter(
                number = 4, title = "The Next Generation", titlePersian = "نسل بعدی",
                paragraphs = listOf(
                    StoryParagraph("After Heathcliff's death, everything changed at Wuthering Heights and Thrushcross Grange.", "بعد از مرگ هیتکلیف، همه چیز در بلندی‌های بادگیر و ثراش‌کراس گرینج تغییر کرد."),
                    StoryParagraph("Cathy and Hareton inherited both houses, and they decided to make Thrushcross Grange their home.", "کتی و هیرتون هر دو خانه را به ارث بردند و تصمیم گرفتند ثراش‌کراس گرینج را خانه خود کنند."),
                    StoryParagraph("Wuthering Heights was closed up and left empty, and it slowly began to fall into ruins.", "بلندی‌های بادگیر بسته شد و خالی ماند و به آرامی شروع به ویران شدن کرد."),
                    StoryParagraph("But Cathy and Hareton did not forget the old house, and they often visited it.", "اما کتی و هیرتون خانه قدیمی را فراموش نکردند و اغلب از آن دیدن می‌کردند."),
                    StoryParagraph("They wanted to repair it and make it a happy place again, free from the dark memories of the past.", "می‌خواستند تعمیرش کنند و دوباره جای شادی کنند، آزاد از خاطرات تاریک گذشته."),
                    StoryParagraph("Hareton worked hard to fix the old house, and Cathy helped him with the garden.", "هیرتون سخت کار کرد تا خانه قدیمی را درست کند و کتی در باغ به او کمک کرد."),
                    StoryParagraph("They planted flowers and vegetables, and they filled the rooms with light and laughter.", "آن‌ها گل و سبزیجات کاشتند و اتاق‌ها را پر از نور و خنده کردند."),
                    StoryParagraph("Slowly, Wuthering Heights became a place of peace and happiness, not of sorrow and pain.", "به آرامی، بلندی‌های بادگیر به جای صلح و خوشبختی تبدیل شد، نه اندوه و درد."),
                    StoryParagraph("Cathy taught Hareton to read and write, and he taught her about the land and the animals.", "کتی به هیرتون خواندن و نوشتن یاد داد و او درباره زمین و حیوانات به او آموخت."),
                    StoryParagraph("They learned from each other, and they grew stronger and wiser together.", "آن‌ها از هم یاد گرفتند و با هم قوی‌تر و داناتر شدند."),
                    StoryParagraph("Their love was not like the love of Heathcliff and Catherine, which had been wild and destructive.", "عشق آن‌ها مثل عشق هیتکلیف و کاترین نبود، که وحشی و مخرب بود."),
                    StoryParagraph("Their love was calm and gentle, built on trust and respect, not on passion and obsession.", "عشق آن‌ها آرام و لطیف بود، بر پایه اعتماد و احترام، نه شور و وسواس."),
                    StoryParagraph("They had learned from the mistakes of the past, and they were determined not to repeat them.", "آن‌ها از اشتباهات گذشته درس گرفته بودند و مصمم بودند تکرارشان نکنند."),
                    StoryParagraph("They had two children, a boy and a girl, and they raised them with love and kindness.", "آن‌ها دو فرزند داشتند، یک پسر و یک دختر، و آن‌ها را با عشق و مهربانی بزرگ کردند."),
                    StoryParagraph("The children grew up happy and healthy, and they never knew the darkness that had haunted their parents.", "بچه‌ها خوشحال و سالم بزرگ شدند و هرگز تاریکی‌ای که والدینشان را تسخیر کرده بود را نشناختند."),
                    StoryParagraph("And so the curse of Wuthering Heights was finally broken, and peace returned to the moors.", "و اینگونه نفرین بلندی‌های بادگیر بالاخره شکست و صلح به دشت‌ها بازگشت."),
                    StoryParagraph("But the story of Heathcliff and Catherine was not forgotten, and it was told for generations.", "اما داستان هیتکلیف و کاترین فراموش نشد و برای نسل‌ها تعریف شد."),
                    StoryParagraph("People said that their love had been too strong for this world, and that it had destroyed them.", "مردم می‌گفتند عشق آن‌ها برای این دنیا خیلی قوی بود و نابودشان کرده بود."),
                    StoryParagraph("Others said that their love had been beautiful, but that it had been twisted by hatred and revenge.", "دیگران می‌گفتند عشقشان زیبا بوده، اما توسط نفرت و انتقام پیچیده شده بود."),
                    StoryParagraph("Whatever the truth, their story remained a warning about the power of love and hate.", "هر حقیقتی که بود، داستانشان هشداری درباره قدرت عشق و نفرت باقی ماند."),
                    StoryParagraph("It reminded people that love can be the greatest gift or the greatest curse.", "به مردم یادآوری می‌کرد عشق می‌تواند بزرگ‌ترین هدیه یا بزرگ‌ترین نفرین باشد."),
                    StoryParagraph("And it reminded them that hate can destroy not only the hater, but also everyone around them.", "و به آن‌ها یادآوری می‌کرد نفرت نه تنها از نفرت‌کننده، بلکه از همه اطرافیانش نابود می‌کند."),
                    StoryParagraph("Cathy and Hareton understood this, and they chose to live their lives with love and forgiveness.", "کتی و هیرتون این را فهمیدند و انتخاب کردند زندگی‌شان را با عشق و بخشش بگذرانند."),
                    StoryParagraph("They forgave Heathcliff for his cruelty, and they forgave Catherine for her weakness.", "هیتکلیف را برای بی‌رحمی‌اش بخشیدند و کاترین را برای ضعفش."),
                    StoryParagraph("They even forgave themselves for the mistakes they had made when they were young and foolish.", "حتی خودشان را برای اشتباهاتی که در جوانی و حماقت مرتکب شده بودند بخشیدند."),
                    StoryParagraph("And so they lived in peace, and they raised their children in peace, and they died in peace.", "و اینگونه در صلح زندگی کردند، فرزندانشان را در صلح بزرگ کردند و در صلح مردند."),
                    StoryParagraph("The moors remained wild and beautiful, and the wind continued to blow across Wuthering Heights.", "دشت‌ها وحشی و زیبا ماندند و باد به وزیدن در بلندی‌های بادگیر ادامه داد."),
                    StoryParagraph("But now the wind carried no cries of sorrow, only the laughter of children playing in the fields.", "اما حالا باد هیچ فریاد اندوهی با خود نمی‌آورد، فقط خنده بچه‌هایی که در مزارع بازی می‌کردند."),
                    StoryParagraph("And so the story of Wuthering Heights ended, but its lessons lived on in the hearts of those who heard it.", "و اینگونه داستان بلندی‌های بادگیر پایان یافت، اما درس‌هایش در قلب کسانی که شنیدند زنده ماند."),
                    StoryParagraph("It is a story of love that was too strong, and of hate that was too deep.", "داستانی است از عشقی که خیلی قوی بود و نفرتی که خیلی عمیق."),
                    StoryParagraph("It is a story of people who could not let go of the past, and who destroyed themselves because of it.", "داستانی است از افرادی که نمی‌توانستند گذشته را رها کنند و به خاطر آن خودشان را نابود کردند."),
                    StoryParagraph("But it is also a story of hope, because in the end, love and peace triumphed over hate and pain.", "اما داستانی از امید هم هست، چون در پایان، عشق و صلح بر نفرت و درد پیروز شدند."),
                    StoryParagraph("And that is the message of Wuthering Heights, a message that is as true today as it was then.", "و این پیام بلندی‌های بادگیر است، پیامی که امروز هم به همان اندازه آن زمان درست است."),
                    StoryParagraph("Love is powerful, but it must be balanced with wisdom and self-control.", "عشق قدرتمند است، اما باید با خرد و خودکنترلی متعادل شود."),
                    StoryParagraph("Hate is destructive, and it will destroy the one who holds it, as well as those around them.", "نفرت مخرب است و کسی که آن را در خود دارد را نابود می‌کند، و همچنین اطرافیانش را."),
                    StoryParagraph("Forgiveness is the only way to break the cycle of pain and revenge.", "بخشش تنها راه شکستن چرخه درد و انتقام است."),
                    StoryParagraph("And peace can only be found when we let go of the past and embrace the future.", "و صلح فقط زمانی یافت می‌شود که گذشته را رها کنیم و آینده را در آغوش بگیریم."),
                    StoryParagraph("That is what Cathy and Hareton learned, and that is what we can all learn from their story.", "این چیزی است که کتی و هیرتون یاد گرفتند و این چیزی است که همه ما می‌توانیم از داستانشان بیاموزیم."),
                    StoryParagraph("And so the story ends, but the moors remain, wild and beautiful, under the endless sky.", "و اینگونه داستان پایان می‌یابد، اما دشت‌ها باقی می‌مانند، وحشی و زیبا، زیر آسمان بی‌پایان."),
                    StoryParagraph("And the wind still blows across Wuthering Heights, whispering the story to those who will listen.", "و باد هنوز در بلندی‌های بادگیر می‌وزد و داستان را برای کسانی که گوش دهند زمزمه می‌کند."),
                    StoryParagraph("The end of one story, but the beginning of another, forever and ever.", "پایان یک داستان، اما آغاز داستانی دیگر، برای همیشه و همیشه.")
                )
            ),
            StoryChapter(
                number = 5, title = "The Haunting", titlePersian = "تسخیر",
                paragraphs = listOf(
                    StoryParagraph("After Heathcliff died, strange things began to happen at Wuthering Heights.", "بعد از مرگ هیتکلیف، چیزهای عجیبی در بلندی‌های بادگیر شروع به اتفاق افتادن کرد."),
                    StoryParagraph("People who passed by the old house at night said they heard voices and saw strange lights.", "کسانی که شب‌ها از کنار خانه قدیمی می‌گذشتند می‌گفتند صداهایی می‌شنوند و نورهای عجیبی می‌بینند."),
                    StoryParagraph("Some said they saw the ghost of Heathcliff walking on the moors, calling Catherine's name.", "بعضی می‌گفتند روح هیتکلیف را دیده‌اند که در دشت‌ها قدم می‌زند و نام کاترین را صدا می‌زند."),
                    StoryParagraph("Others said they saw a woman in white, standing at the window of the old house.", "دیگران می‌گفتند زنی سفیدپوش را دیده‌اند که کنار پنجره خانه قدیمی ایستاده است."),
                    StoryParagraph("The villagers were afraid, and they avoided the house after dark.", "روستاییان ترسیدند و بعد از تاریکی از خانه دوری می‌کردند."),
                    StoryParagraph("But Cathy and Hareton were not afraid, because they did not believe in ghosts.", "اما کتی و هیرتون نمی‌ترسیدند، چون به ارواح اعتقاد نداشتند."),
                    StoryParagraph("They believed that the strange sights and sounds were just the wind and the animals of the moors.", "آن‌ها باور داشتند مناظر و صداهای عجیب فقط باد و حیوانات دشت هستند."),
                    StoryParagraph("But one night, Cathy saw something that made her change her mind.", "اما یک شب، کتی چیزی دید که نظرش را تغییر داد."),
                    StoryParagraph("She was walking alone on the moors when she saw two figures standing together in the distance.", "او تنها در دشت‌ها قدم می‌زد که دو چهره را در دوردست دید که کنار هم ایستاده بودند."),
                    StoryParagraph("One was a tall, dark man, and the other was a beautiful woman with golden hair.", "یکی مردی بلندقد و تیره بود و دیگری زنی زیبا با موهای طلایی."),
                    StoryParagraph("They were holding hands and looking at each other with great love.", "آن‌ها دست هم را گرفته بودند و با عشق فراوان به هم نگاه می‌کردند."),
                    StoryParagraph("Cathy knew immediately who they were: Heathcliff and Catherine, united at last.", "کتی فوراً فهمید آن‌ها کیستند: هیتکلیف و کاترین، بالاخره متحد شده بودند."),
                    StoryParagraph("She was not afraid, but she felt a deep sadness and a strange peace at the same time.", "او نترسید، اما همزمان غم عمیقی و آرامش عجیبی حس کرد."),
                    StoryParagraph("The figures slowly faded away, and Cathy was left alone on the dark moor.", "چهره‌ها به آرامی محو شدند و کتی در دشت تاریک تنها ماند."),
                    StoryParagraph("She went home and told Hareton what she had seen, and he listened quietly.", "او به خانه رفت و به هیرتون گفت چه دیده و او آرام گوش داد."),
                    StoryParagraph("He said that he believed her, because he had also felt the presence of something strange on the moors.", "او گفت باورش دارد، چون او هم حضور چیزی عجیب را در دشت‌ها حس کرده بود."),
                    StoryParagraph("They decided that they would not be afraid, because the ghosts were not evil.", "تصمیم گرفتند نترسند، چون ارواح شیطانی نبودند."),
                    StoryParagraph("They were just two souls who had loved each other too much to be separated, even by death.", "آن‌ها فقط دو روح بودند که آنقدر یکدیگر را دوست داشتند که حتی مرگ هم نتوانست جداشان کند."),
                    StoryParagraph("And so Cathy and Hareton made peace with the ghosts of the past, and they lived without fear.", "و اینگونه کتی و هیرتون با ارواح گذشته صلح کردند و بدون ترس زندگی کردند."),
                    StoryParagraph("They continued to repair Wuthering Heights, and they made it a place of warmth and love.", "آن‌ها به تعمیر بلندی‌های بادگیر ادامه دادند و آن را جای گرمی و عشق کردند."),
                    StoryParagraph("The old house, which had once been dark and cold, was now full of light and laughter.", "خانه قدیمی که زمانی تاریک و سرد بود، حالا پر از نور و خنده بود."),
                    StoryParagraph("The garden was full of flowers, and the rooms were filled with the smell of fresh bread.", "باغ پر از گل بود و اتاق‌ها پر از بوی نان تازه."),
                    StoryParagraph("Children ran through the halls, and their laughter echoed where once there had been only silence.", "بچه‌ها در راهروها می‌دویدند و خنده‌شان جایی را پر می‌کرد که روزی فقط سکوت بود."),
                    StoryParagraph("Cathy and Hareton grew old together, and their love only grew stronger with time.", "کتی و هیرتون با هم پیر شدند و عشقشان فقط با گذر زمان قوی‌تر شد."),
                    StoryParagraph("They never forgot the story of Heathcliff and Catherine, but they did not let it darken their lives.", "هرگز داستان هیتکلیف و کاترین را فراموش نکردند، اما اجازه ندادند زندگی‌شان را تاریک کند."),
                    StoryParagraph("Instead, they learned from it, and they used those lessons to build a better life for themselves.", "در عوض، از آن درس گرفتند و از آن درس‌ها برای ساختن زندگی بهتر برای خودشان استفاده کردند."),
                    StoryParagraph("They taught their children about love and hate, and about the importance of forgiveness.", "به فرزندانشان درباره عشق و نفرت و اهمیت بخشش آموختند."),
                    StoryParagraph("They told them the story of Wuthering Heights, not as a ghost story, but as a lesson in life.", "داستان بلندی‌های بادگیر را برایشان تعریف کردند، نه به عنوان داستان ترسناک، بلکه به عنوان درسی از زندگی."),
                    StoryParagraph("And the children listened, and they learned, and they grew up to be kind and wise.", "و بچه‌ها گوش دادند، یاد گرفتند و مهربان و دانا بزرگ شدند."),
                    StoryParagraph("And so the cycle of pain and revenge was finally broken, and a new cycle of love and peace began.", "و اینگونه چرخه درد و انتقام بالاخره شکست و چرخه جدیدی از عشق و صلح آغاز شد."),
                    StoryParagraph("The moors remained wild and beautiful, and the wind continued to blow across Wuthering Heights.", "دشت‌ها وحشی و زیبا ماندند و باد به وزیدن در بلندی‌های بادگیر ادامه داد."),
                    StoryParagraph("But now the wind carried only the sounds of nature and the laughter of children.", "اما حالا باد فقط صداهای طبیعت و خنده بچه‌ها را با خود می‌آورد."),
                    StoryParagraph("The ghosts of Heathcliff and Catherine were at peace, and they no longer haunted the old house.", "ارواح هیتکلیف و کاترین در آرامش بودند و دیگر خانه قدیمی را تسخیر نمی‌کردند."),
                    StoryParagraph("They had finally found what they had been searching for all their lives: peace and union.", "آن‌ها بالاخره چیزی که تمام زندگی‌شان دنبالش بودند را یافته بودند: صلح و اتحاد."),
                    StoryParagraph("And so the story of Wuthering Heights came to an end, but its memory lived on forever.", "و اینگونه داستان بلندی‌های بادگیر به پایان رسید، اما خاطره‌اش برای همیشه زنده ماند."),
                    StoryParagraph("It was a story of passion and pain, of love and hate, of revenge and redemption.", "داستانی بود از شور و درد، از عشق و نفرت، از انتقام و رستگاری."),
                    StoryParagraph("It was a story that reminded us that love can be both beautiful and terrible.", "داستانی بود که به ما یادآوری می‌کرد عشق می‌تواند هم زیبا و هم وحشتناک باشد."),
                    StoryParagraph("And it was a story that taught us that forgiveness is the only way to true peace.", "و داستانی بود که به ما آموخت بخشش تنها راه صلح واقعی است."),
                    StoryParagraph("And so the wind blows across the moors, and the story is told, and will be told forever.", "و اینگونه باد در دشت‌ها می‌وزد و داستان گفته می‌شود و برای همیشه گفته خواهد شد.")
                )
            ),
            StoryChapter(
                number = 6, title = "The Legacy", titlePersian = "میراث",
                paragraphs = listOf(
                    StoryParagraph("Many years passed, and the story of Wuthering Heights became a legend in the area.", "سال‌ها گذشت و داستان بلندی‌های بادگیر به افسانه‌ای در منطقه تبدیل شد."),
                    StoryParagraph("People told it to their children, and their children told it to their children.", "مردم آن را برای فرزندانشان تعریف کردند و فرزندانشان برای فرزندانشان."),
                    StoryParagraph("It became a story of warning, a story of what happens when love turns to obsession.", "به داستانی هشداردهنده تبدیل شد، داستانی از آنچه وقتی عشق به وسواس تبدیل می‌شود اتفاق می‌افتد."),
                    StoryParagraph("But it also became a story of hope, a story of how peace can be found after great pain.", "اما به داستانی امیدبخش هم تبدیل شد، داستانی از اینکه چگونه صلح بعد از درد بزرگ یافت می‌شود."),
                    StoryParagraph("Cathy and Hareton lived long and happy lives, and they were respected by everyone who knew them.", "کتی و هیرتون زندگی طولانی و خوشحالی داشتند و مورد احترام همه کسانی بودند که می‌شناختندشان."),
                    StoryParagraph("They raised their children with love and kindness, and they taught them the lessons of the past.", "فرزندانشان را با عشق و مهربانی بزرگ کردند و درس‌های گذشته را به آن‌ها آموختند."),
                    StoryParagraph("Their children grew up to be good and wise people, and they in turn raised good and wise children.", "فرزندانشان به افراد خوب و دانا تبدیل شدند و آن‌ها هم به نوبت فرزندان خوب و دانا بزرگ کردند."),
                    StoryParagraph("And so the legacy of Wuthering Heights was not one of hatred and revenge, but of love and forgiveness.", "و اینگونه میراث بلندی‌های بادگیر نه نفرت و انتقام، بلکه عشق و بخشش بود."),
                    StoryParagraph("The old house was eventually turned into a museum, and people came from all over to visit it.", "خانه قدیمی در نهایت به موزه تبدیل شد و مردم از همه جا برای دیدنش می‌آمدند."),
                    StoryParagraph("They walked through the rooms where Heathcliff and Catherine had lived and loved.", "آن‌ها در اتاق‌هایی قدم می‌زدند که هیتکلیف و کاترین در آن زندگی و عشق ورزیده بودند."),
                    StoryParagraph("They stood by the window where Catherine's ghost was said to have appeared.", "کنار پنجره‌ای می‌ایستادند که گفته می‌شد روح کاترین آنجا ظاهر شده است."),
                    StoryParagraph("They looked out over the wild moors that had been the backdrop of so much passion and pain.", "به دشت‌های وحشی که پس‌زمینه این همه شور و درد بود نگاه می‌کردند."),
                    StoryParagraph("The guides told the story of Heathcliff and Catherine, and the visitors listened in silence.", "راهنماها داستان هیتکلیف و کاترین را تعریف می‌کردند و بازدیدکنندگان در سکوت گوش می‌دادند."),
                    StoryParagraph("Some of them cried, and some of them shuddered, and some of them simply shook their heads.", "بعضی گریه می‌کردند، بعضی می‌لرزیدند و بعضی فقط سر تکان می‌دادند."),
                    StoryParagraph("But all of them felt something, because the story touched something deep inside them.", "اما همه چیزی حس می‌کردند، چون داستان چیزی عمیق در درونشان را لمس می‌کرد."),
                    StoryParagraph("It reminded them of their own loves and losses, their own joys and sorrows.", "آن‌ها را به یاد عشق‌ها و فقدان‌های خودشان، شادی‌ها و غم‌های خودشان می‌انداخت."),
                    StoryParagraph("It reminded them that life is short, and that we should cherish the people we love.", "به آن‌ها یادآوری می‌کرد زندگی کوتاه است و باید افرادی که دوستشان داریم را قدر بدانیم."),
                    StoryParagraph("It reminded them that hate destroys, and that forgiveness heals.", "به آن‌ها یادآوری می‌کرد نفرت نابود می‌کند و بخشش شفا می‌دهد."),
                    StoryParagraph("It reminded them that the past cannot be changed, but the future can be shaped.", "به آن‌ها یادآوری می‌کرد گذشته را نمی‌توان تغییر داد، اما آینده را می‌توان ساخت."),
                    StoryParagraph("And it reminded them that love, when it is pure and true, never dies.", "و به آن‌ها یادآوری می‌کرد عشق، وقتی خالص و واقعی باشد، هرگز نمی‌میرد."),
                    StoryParagraph("Cathy and Hareton eventually died, old and content, surrounded by their family.", "کتی و هیرتون در نهایت مردند، پیر و راضی، در میان خانواده‌شان."),
                    StoryParagraph("They were buried on the moors, near the graves of Heathcliff and Catherine.", "آن‌ها در دشت‌ها دفن شدند، نزدیک قبرهای هیتکلیف و کاترین."),
                    StoryParagraph("And so, in death, they were all united, the four of them, in the wild and beautiful land they had loved.", "و اینگونه، در مرگ، همه آن‌ها متحد شدند، آن چهار نفر، در سرزمین وحشی و زیبایی که دوست داشتند."),
                    StoryParagraph("Some say that on quiet nights, you can still hear their voices on the wind.", "بعضی می‌گویند در شب‌های آرام، هنوز می‌توانی صدایشان را در باد بشنوی."),
                    StoryParagraph("Some say that their ghosts still walk together on the moors, watching over the land they loved.", "بعضی می‌گویند ارواحشان هنوز با هم در دشت‌ها قدم می‌زنند و بر سرزمینی که دوست داشتند نظارت می‌کنند."),
                    StoryParagraph("And some say that their love, which had been so powerful in life, had become part of the land itself.", "و بعضی می‌گویند عشقشان، که در زندگی اینقدر قدرتمند بود، بخشی از خود زمین شده است."),
                    StoryParagraph("Whether these stories are true or not, no one can say for certain.", "اینکه این داستان‌ها درست هستند یا نه، هیچ‌کس نمی‌تواند با اطمینان بگوید."),
                    StoryParagraph("But what is certain is that the story of Wuthering Heights will never be forgotten.", "اما آنچه مسلم است این است که داستان بلندی‌های بادگیر هرگز فراموش نخواهد شد."),
                    StoryParagraph("It will be told and retold, in books and in films, in plays and in songs.", "تعریف و بازتعریف خواهد شد، در کتاب‌ها و فیلم‌ها، در نمایش‌ها و آهنگ‌ها."),
                    StoryParagraph("It will continue to touch the hearts of people all over the world, in every generation.", "به لمس کردن قلب‌های مردم سراسر جهان ادامه خواهد داد، در هر نسلی."),
                    StoryParagraph("Because it is not just a story about two people; it is a story about all of us.", "چون فقط داستانی درباره دو نفر نیست؛ داستانی درباره همه ماست."),
                    StoryParagraph("It is a story about the human heart, with all its beauty and all its darkness.", "داستانی است درباره قلب انسان، با تمام زیبایی و تمام تاریکی‌اش."),
                    StoryParagraph("It is a story about the choices we make, and the consequences that follow.", "داستانی است درباره انتخاب‌هایی که می‌کنیم و پیامدهایی که در پی می‌آید."),
                    StoryParagraph("It is a story about love, and hate, and forgiveness, and redemption.", "داستانی است درباره عشق، نفرت، بخشش و رستگاری."),
                    StoryParagraph("And it is a story that reminds us that we are all connected, in life and in death.", "و داستانی است که به ما یادآوری می‌کند همه ما در زندگی و مرگ به هم متصل هستیم."),
                    StoryParagraph("So let us remember the story of Wuthering Heights, and let us learn from it.", "پس بیایید داستان بلندی‌های بادگیر را به یاد بیاوریم و از آن درس بگیریم."),
                    StoryParagraph("Let us love deeply, but wisely. Let us forgive freely, and let go of hate.", "بیایید عمیق اما عاقلانه عشق بورزیم. بیایید آزادانه ببخشیم و نفرت را رها کنیم."),
                    StoryParagraph("And let us live our lives in peace, knowing that love is the only thing that truly lasts.", "و بیایید زندگی‌مان را در صلح بگذرانیم، با دانستن اینکه عشق تنها چیزی است که واقعاً باقی می‌ماند."),
                    StoryParagraph("And so the story ends, but the moors remain, wild and beautiful, under the endless sky.", "و اینگونه داستان پایان می‌یابد، اما دشت‌ها باقی می‌مانند، وحشی و زیبا، زیر آسمان بی‌پایان."),
                    StoryParagraph("And the wind still blows across Wuthering Heights, whispering the story to those who will listen.", "و باد هنوز در بلندی‌های بادگیر می‌وزد و داستان را برای کسانی که گوش دهند زمزمه می‌کند."),
                    StoryParagraph("The end.", "پایان."),
                    StoryParagraph("But the story continues, forever and ever.", "اما داستان ادامه دارد، برای همیشه و همیشه.")
                )
            )
        )
    )
}